'use strict';
const uiPages=['settings','help','about','access'];
const renderBeforeUI=render,navBeforeUI=nav;
profileLinks=function(){return `<section class="card profile-settings"><h3>Make yourself at home.</h3><p class="hint">Appearance, privacy, support, and information about this app.</p><button class="profile-action" data-nav="settings"><span>Settings & support</span><small>Open →</small></button><button class="profile-action" data-nav="help"><span>How to use the Hub</span><small>Quick guide →</small></button></section>`};
function settingsUI(){app.innerHTML=`<button class="back" data-nav="profile">← Profile</button><header class="ui-page-head"><span class="eyebrow">YOUR APP / YOUR PREFERENCES</span><h1>Settings & support</h1><p>Keep it comfortable. Find help when you need it.</p></header><section class="card"><h2 class="ui-section-title">Appearance</h2><p class="hint">Choose a light or dark reading space.</p><div class="theme-options"><button data-theme-choice="light" aria-pressed="${state.theme==='light'}" class="${state.theme==='light'?'active':''}">☀ Light</button><button data-theme-choice="dark" aria-pressed="${state.theme==='dark'}" class="${state.theme==='dark'?'active':''}">☾ Dark</button></div></section><section class="card ui-menu">${[['access','Account & storage','What is saved on this device'],['privacy','Privacy policy','Understand your information'],['help','How to use the Hub','Find your way around'],['feedback','Feedback','Tell JV what needs improving'],['community','Facebook community','Official group link status'],['about','About the Hub','Purpose, creator, and prototype status']].map(([p,title,sub])=>`<button class="profile-action" data-nav="${p}"><span><strong>${title}</strong><small>${sub}</small></span><b aria-hidden="true">›</b></button>`).join('')}</section>`}
function helpUI(){app.innerHTML=`<button class="back" data-nav="settings">← Settings & support</button><header class="ui-page-head"><span class="eyebrow">START WITH WHAT YOU NEED</span><h1>Your way around the Hub.</h1><p>Each tab has one job. These shortcuts take you to the existing screens.</p></header><div class="ui-guide-grid">${[['01','Contribute','Ask with context or choose topics you can answer. Add permitted photos when they help explain the problem.','home','Ask or answer'],['02','Library','Choose a department topic first, then open a question file. Its complete discussion stays together there.','learn','Find a topic'],['03','Review','Pick OIC NW or OIC EW, choose a practice set, and take a short round. Reading mode is unscored.','review','Open reviewer'],['04','Progress','See participation badges, contribution activity, and the sample Top seafarers board. Quiz scores remain separate.','progress','See progress'],['05','Profile','Your name, rank, bio, and photo live here. Use the small Edit button to make changes.','profile','View profile']].map(([n,title,copy,p,label])=>`<section class="card ui-guide"><span class="ui-step">${n}</span><h2>${title}</h2><p>${copy}</p><button class="btn quiet" data-nav="${p}">${label} →</button></section>`).join('')}</div><div class="note"><strong>Navigation tip:</strong> Use the bottom tabs on phones or the sidebar on larger screens. Search answers opens the existing question search. Back links return you to the relevant parent screen.</div>`}
function accessUI(){app.innerHTML=`<button class="back" data-nav="settings">← Settings & support</button><header class="ui-page-head"><span class="eyebrow">ACCOUNT & STORAGE</span><h1>Your workspace, on this device.</h1><p>A clear picture of how this prototype works today.</p></header><section class="card"><span class="ui-status-pill">BROWSER-LOCAL PROTOTYPE</span><h2>You're using a local profile.</h2><p>Your profile email does not create an account or sign you in. There is no password, verified email, or cloud account connected yet.</p><p><strong>Your questions, answers, photos, bookmarks, and quiz progress stay in this browser.</strong> A different browser or device has a separate workspace. Clearing site data removes the local records.</p><p>This is why there is no working sign-in, sign-out, or password-reset form at this stage. Those screens belong with real authentication and cloud storage.</p><button class="btn quiet" data-nav="profile">View my local profile →</button></section><section class="card"><h2>When shared accounts are ready</h2><p>The app will need verified sign-in, account recovery, protected cloud records, and tested restore across devices before it can host a shared Q&A community. Your current records are not being uploaded automatically.</p><button class="text-button" data-nav="privacy">Read the current privacy notice →</button></section>`}
function aboutUI(){app.innerHTML=`<button class="back" data-nav="settings">← Settings & support</button><section class="card ui-about"><img src="assets/seafarer-mascot.webp" alt="Bulletproof Seafarers mascot"><span class="eyebrow">BY JV URSAL / BULLETPROOF SEAFARERS</span><h1>Experience shared.<br>Knowledge kept.</h1><p>The Hub began with a simple observation: useful seafarer questions and answers get buried in busy group chats.</p><p>Our purpose is to keep each question, its context, and shared experience together in a searchable Library across engine, deck, electrical, and shipboard topics. Optional OIC practice adds a space to review at your own pace.</p><p><strong>A contribution can help the next crew.</strong> Badges recognize participation; they do not verify competence. Community suggestions and provisional reviewer keys need appropriate checking.</p><div class="ui-status-pill">FREE PROTOTYPE · VERSION 0.9</div><p class="hint">Browser-local records. Shared accounts and cloud sync are not connected yet.</p><button class="btn" data-nav="feedback">Help improve the Hub →</button></section>`}
nav=function(p){if(uiPages.includes(p)&&state.hubOnboardingCompleted){page=p;selected=null;render();window.scrollTo(0,0);return}navBeforeUI(p)};
function uiHeader(){if(!state.hubOnboardingCompleted)return;const top=document.querySelector('.topbar');if(!document.querySelector('#uiProfileShortcut'))top.insertAdjacentHTML('beforeend',`<button class="ui-profile-shortcut" id="uiProfileShortcut" data-nav="profile" aria-label="Open your profile">${state.profile.photo?`<img src="${esc(state.profile.photo)}" alt="">`:`<span>${esc(qProfileName().slice(0,2).toUpperCase())}</span>`}</button>`)}
render=function(){if(uiPages.includes(page)&&state.hubOnboardingCompleted){applyTheme();document.body.classList.remove('intro-mode');app.classList.remove('setup-view');renderNav();for(const id of ['desktopNav','mobileNav']){const target=document.getElementById(id).querySelector('[data-nav="profile"]');target?.classList.add('active');target?.setAttribute('aria-current','page')}document.querySelector('#sectionName').textContent=({settings:'Settings & support',help:'Your quick guide',about:'About the Hub',access:'Account & storage'})[page];({settings:settingsUI,help:helpUI,about:aboutUI,access:accessUI})[page]();animatePolishedRoute();saveLastView()}else renderBeforeUI();uiHeader()};
render();
